"""matplotlib._afm — Adobe Font Metrics reader stub.

Real matplotlib parses .afm files to size Type 1 fonts for the PostScript
and PDF backends. The plotly backend doesn't render via either, so this
module is here only to satisfy imports.
"""


class AFM:
    """Parsed Adobe Font Metrics. The shim does a minimal line-by-line
    parse of the AFM header + per-glyph width table — enough to size
    strings when an .afm file is loaded. When no file is provided, the
    defaults match a 10-point Helvetica (the upstream fallback)."""

    def __init__(self, fh=None):
        self._header = {
            'FontName':          'Helvetica',
            'FamilyName':        'Helvetica',
            'FullName':          'Helvetica',
            'Weight':            'normal',
            'ItalicAngle':       0.0,
            'IsFixedPitch':      False,
            'CapHeight':         718,
            'XHeight':           523,
            'UnderlineThickness': 50,
            'UnderlinePosition': -100,
            'StdHW':             76,
            'StdVW':             88,
        }
        self._char_metrics_by_name = {}  # name → CharMetrics
        self._char_metrics_by_code = {}  # ord → CharMetrics
        self._kern = {}                  # (c1, c2) → dx
        self._composite = {}             # name → [CompositePart]
        if fh is not None:
            try:
                self._parse(fh)
            except Exception:
                # Bad/unsupported AFM — keep defaults.
                pass

    def _parse(self, fh):
        """Parse a minimal subset of the AFM format: header key/value
        pairs and the StartCharMetrics block. Anything we don't
        recognise is ignored."""
        lines = (fh.read() if hasattr(fh, 'read') else fh).splitlines()
        in_chars = False
        for line in lines:
            line = line.strip() if isinstance(line, str) else line.decode('utf-8', errors='replace').strip()
            if not line: continue
            if line.startswith('StartCharMetrics'):
                in_chars = True; continue
            if line.startswith('EndCharMetrics'):
                in_chars = False; continue
            if in_chars:
                # Format: C <code> ; WX <width> ; N <name> ; B x1 y1 x2 y2 ;
                code = -1; width = 0; name = ''; bbox = (0, 0, 0, 0)
                for chunk in line.split(';'):
                    parts = chunk.strip().split()
                    if not parts: continue
                    k = parts[0]
                    if k == 'C':     code = int(parts[1])
                    elif k == 'WX':  width = float(parts[1])
                    elif k == 'N':   name = parts[1]
                    elif k == 'B' and len(parts) >= 5:
                        bbox = tuple(float(x) for x in parts[1:5])
                cm = CharMetrics(width=width, name=name, bbox=bbox)
                if name: self._char_metrics_by_name[name] = cm
                if code >= 0: self._char_metrics_by_code[code] = cm
                continue
            # Header key/value.
            parts = line.split(None, 1)
            if len(parts) == 2:
                key, val = parts
                # Coerce common numeric fields.
                if key in ('CapHeight', 'XHeight', 'UnderlineThickness',
                            'UnderlinePosition', 'StdHW', 'StdVW'):
                    try: val = int(float(val))
                    except ValueError: pass
                elif key == 'ItalicAngle':
                    try: val = float(val)
                    except ValueError: pass
                elif key == 'IsFixedPitch':
                    val = val.lower() == 'true'
                self._header[key] = val

    def get_str_bbox_and_descent(self, s):
        """Return ``(x0, y0, x1, y1, descent)`` for the string ``s``."""
        w = 0; max_h = 0; min_y = 0
        for ch in s:
            cm = self._char_metrics_by_code.get(ord(ch))
            if cm is None: continue
            w += cm.width
            x0, y0, x1, y1 = cm.bbox
            max_h = max(max_h, y1)
            min_y = min(min_y, y0)
        return (0, min_y, w, max_h, -min_y)

    def get_str_bbox(self, s):
        return self.get_str_bbox_and_descent(s)[:4]

    def get_kern_dist(self, c1, c2):
        return self._kern.get((c1, c2), 0)

    def get_width_char(self, c):
        cm = self._char_metrics_by_code.get(ord(c) if isinstance(c, str) else c)
        return cm.width if cm else 0

    def get_width_from_char_name(self, name):
        cm = self._char_metrics_by_name.get(name)
        return cm.width if cm else 0

    def get_height_char(self, c):
        cm = self._char_metrics_by_code.get(ord(c) if isinstance(c, str) else c)
        return (cm.bbox[3] - cm.bbox[1]) if cm else 0

    def get_horizontal_stem_width(self): return self._header.get('StdHW', 0)
    def get_vertical_stem_width(self):   return self._header.get('StdVW', 0)
    def get_familyname(self):            return self._header['FamilyName']
    def get_fontname(self):              return self._header['FontName']
    def get_fullname(self):              return self._header['FullName']
    def get_capheight(self):             return self._header.get('CapHeight', 0)
    def get_xheight(self):               return self._header.get('XHeight', 0)
    def get_underline_thickness(self):   return self._header.get('UnderlineThickness', 0)
    def get_weight(self):                return self._header.get('Weight', 'normal')
    def get_angle(self):                 return self._header.get('ItalicAngle', 0)

    def get_bbox_char(self, c, isord=False):
        code = c if isord else (ord(c) if isinstance(c, str) else c)
        cm = self._char_metrics_by_code.get(code)
        return cm.bbox if cm else (0, 0, 0, 0)


def parse_afm(fh):
    """Top-level AFM parser entry point. Returns
    ``(header_dict, char_metrics_by_code, char_metrics_by_name, kern_dict)``
    matching upstream's tuple shape."""
    afm = AFM(fh)
    return (dict(afm._header),
            dict(afm._char_metrics_by_code),
            dict(afm._char_metrics_by_name),
            dict(afm._kern))


def parse_header(fh):
    return AFM(fh)._header


def parse_char_metrics(fh):
    a = AFM(fh)
    return a._char_metrics_by_code, a._char_metrics_by_name


def parse_kern_pairs(fh):
    return AFM(fh)._kern


def parse_composites(fh):
    return AFM(fh)._composite


# ─── Added: missing public names from upstream _afm.py ─────────────


from collections import namedtuple


# Public namedtuples that AFM-parsing code returns.
CharMetrics = namedtuple('CharMetrics', ['width', 'name', 'bbox'])
CompositePart = namedtuple('CompositePart', ['name', 'dx', 'dy'])
